export const toastCss = ".kalos-toast,.kalos-toast-viewport{--kalos-toast-radius:9999px;--kalos-toast-min-height:40px;--kalos-toast-padding-x:14px;--kalos-toast-padding-y:6px;--kalos-toast-gap:10px;--kalos-toast-viewport-width:512px;--kalos-toast-top:20px;--kalos-toast-duration:300ms;--kalos-toast-font:Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", ByteSans, Arial, "Helvetica Neue", -apple-system, BlinkMacSystemFont, "noto sans", Helvetica, sans-serif;--kalos-toast-ease:cubic-bezier(0.22, 1, 0.36, 1);--kalos-toast-surface:#ffffff;--kalos-toast-ink:#17202b;--kalos-toast-muted:#7b8898;--kalos-toast-shadow:0 4px 12px #00000014;--kalos-toast-brand:#165dff;--kalos-toast-success:#18b596;--kalos-toast-warning:#f19021;--kalos-toast-error:#ff3e27;--kalos-toast-on-status:#ffffff;--kalos-toast-focus:#165dff;--kalos-toast-button-edge:#e3e9ef;--kalos-toast-button-surface:#ffffff;--kalos-toast-hover:#f3f5f8}
:where(.dark,[data-theme=dark]) .kalos-toast{--kalos-toast-surface:#202020;--kalos-toast-ink:#ededed;--kalos-toast-muted:#a1a1a1;--kalos-toast-shadow:0 4px 12px #00000040;--kalos-toast-brand:#2f6fef;--kalos-toast-success:#18b596;--kalos-toast-warning:#f19021;--kalos-toast-error:#ff3e27;--kalos-toast-on-status:#ffffff;--kalos-toast-focus:#5b8cff;--kalos-toast-button-edge:#404040;--kalos-toast-button-surface:#171717;--kalos-toast-hover:#262626}
.kalos-toast-viewport {
  position: fixed;
  inset: var(--kalos-toast-top) 16px auto;
  isolation: isolate;
  z-index: 60;
  width: auto;
  max-width: var(--kalos-toast-viewport-width);
  margin-inline: auto;
  pointer-events: none;
  outline: none;
}
@media (min-width: 768px) and (max-width: 1679px) {
  .kalos-toast-portal {
    position: fixed;
    inset: 0 auto auto 0;
    z-index: 60;
    width: 125vw;
    height: 125svh;
    transform: scale(0.8);
    transform-origin: top left;
    pointer-events: none;
  }
