.kalos-toast, .kalos-toast * { box-sizing: border-box; }
.kalos-toast {
  --gap: 12px;
  --peek: 12px;
  --scale: calc(max(0, 1 - (var(--toast-index) * 0.1)));
  --shrink: calc(1 - var(--scale));
  --height: var(--toast-frontmost-height, var(--toast-height));
  --offset-y: calc(var(--toast-offset-y) + (var(--toast-index) * var(--gap)) + var(--toast-swipe-movement-y));
  position: absolute;
  inset: 0 0 auto;
  isolation: isolate;
  z-index: calc(1000 - var(--toast-index));
  width: max-content;
  max-width: 100%;
  height: var(--height);
  margin-inline: auto;
  border-radius: var(--kalos-toast-radius);
  color: var(--kalos-toast-ink);
  font-family: var(--kalos-toast-font);
  font-size: 14px;
  line-height: 20px;
  font-weight: 400;
  outline: none;
  pointer-events: auto;
  user-select: none;
  transform-origin: top;
  transform: translateX(var(--toast-swipe-movement-x)) translateY(calc(var(--toast-swipe-movement-y) + (var(--toast-index) * var(--peek)) + (var(--shrink) * var(--height)))) scale(var(--scale));
  transition: transform 200ms var(--kalos-toast-ease), opacity 180ms ease-out, height 150ms;
  will-change: transform, opacity;
}
.kalos-toast::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 50%;
  z-index: -1;
  width: 100%;
  transform: translateX(-50%);
  border-radius: inherit;
  background: var(--kalos-toast-surface);
  box-shadow: var(--kalos-toast-shadow);
  transition: width var(--kalos-toast-duration) var(--kalos-toast-ease);
}
.kalos-toast::after { content: ""; position: absolute; top: 100%; left: 0; width: 100%; height: calc(var(--gap) + 1px); }
.kalos-toast:focus-visible { box-shadow: 0 0 0 3px color-mix(in srgb, var(--kalos-toast-focus) 50%, transparent); }
.kalos-toast[data-expanded] { height: var(--toast-height); transform: translateX(var(--toast-swipe-movement-x)) translateY(var(--offset-y)); }
.kalos-toast:is([data-starting-style], [data-ending-style], [data-limited]) { opacity: 0; }
.kalos-toast[data-ending-style][data-swipe-direction="up"] { transform: translateY(calc(var(--toast-swipe-movement-y) - 150%)); }
.kalos-toast[data-ending-style][data-swipe-direction="down"] { transform: translateY(calc(var(--toast-swipe-movement-y) + 150%)); }
.kalos-toast[data-ending-style][data-swipe-direction="left"] { transform: translateX(calc(var(--toast-swipe-movement-x) - 150%)) translateY(var(--offset-y)); }
.kalos-toast[data-ending-style][data-swipe-direction="right"] { transform: translateX(calc(var(--toast-swipe-movement-x) + 150%)) translateY(var(--offset-y)); }
.kalos-toast-content {
  display: flex;
  min-height: var(--kalos-toast-min-height);
  align-items: center;
  gap: var(--kalos-toast-gap);
  overflow: hidden;
  border-radius: inherit;
  padding: var(--kalos-toast-padding-y) var(--kalos-toast-padding-x);
  clip-path: inset(0 0 round 9999px);
  transition: clip-path var(--kalos-toast-duration) var(--kalos-toast-ease), opacity 180ms ease-out;
}
.kalos-toast-content[data-behind] { opacity: 0; }
.kalos-toast-content[data-expanded] { opacity: 1; }
.kalos-toast[data-starting-style] .kalos-toast-content,
.kalos-toast[data-ending-style]:not([data-swipe-direction]) .kalos-toast-content { clip-path: inset(0 50% round 9999px); opacity: 0; transition-delay: 0ms, 0ms; }
.kalos-toast[data-starting-style]::before,
.kalos-toast[data-ending-style]:not([data-swipe-direction])::before { width: 0; }
.kalos-toast-text { display: flex; flex: 1; min-width: 0; flex-direction: column; gap: 4px; }
.kalos-toast-title, .kalos-toast-description { margin: 0; font: inherit; overflow-wrap: anywhere; }
.kalos-toast-description { color: var(--kalos-toast-muted); }
.kalos-toast-action[data-slot], .kalos-toast-close[data-slot] {
  flex-shrink: 0;
  height: 24px;
  border-radius: 12px;
  font-family: inherit;
  font-size: 12px;
  line-height: 16px;
  font-weight: 400;
  box-shadow: none;
  transition: background-color 150ms, color 150ms;
}
.kalos-toast-action[data-slot] { gap: 4px; padding: 0 10px; border: 1px solid var(--kalos-toast-button-edge); background: var(--kalos-toast-button-surface); color: var(--kalos-toast-ink); }
.kalos-toast-close[data-slot] { position: relative; width: 24px; padding: 0; border: 1px solid transparent; background: transparent; color: var(--kalos-toast-muted); }
.kalos-toast-close::after { content: ""; position: absolute; inset: -8px; }
.kalos-toast-action[data-slot]:hover:not(:disabled), .kalos-toast-close[data-slot]:hover:not(:disabled) { background: var(--kalos-toast-hover); color: var(--kalos-toast-ink); }
.kalos-toast-action:focus-visible, .kalos-toast-close:focus-visible { outline: 2px solid var(--kalos-toast-focus); outline-offset: 2px; }
.kalos-toast-close[data-slot] svg { width: 12px; height: 12px; }
.kalos-toast-icon { display: flex; width: 16px; height: 16px; flex-shrink: 0; align-items: center; justify-content: center; border-radius: 50%; color: var(--kalos-toast-on-status); }
.kalos-toast-icon svg { width: 12px; height: 12px; pointer-events: none; }
.kalos-toast-icon[data-type="success"] { background: var(--kalos-toast-success); }
.kalos-toast-icon[data-type="info"] { background: var(--kalos-toast-brand); }
.kalos-toast-icon[data-type="warning"] { background: var(--kalos-toast-warning); }
.kalos-toast-icon[data-type="error"] { background: var(--kalos-toast-error); }
.kalos-toast-icon > span { font-size: 10px; line-height: 1; font-weight: 700; }
.kalos-toast-icon[data-type="loading"] { color: var(--kalos-toast-brand); }
.kalos-toast-icon[data-type="loading"] svg { width: 16px; height: 16px; animation: kalos-toast-spin 1s linear infinite; }
@keyframes kalos-toast-spin { to { transform: rotate(360deg); } }
